    "memoryKeys": "ParticipationBatch, LastPush",
    "decisionReasonTemplate": "Never report each like/comment individually. Collect activity for this recipient in a 15-minute window; when the window closes, send ONE summary push with a count (e.g. \"5 people commented on your Seedling in the past 15 minutes\"). Tapping the notification takes the user directly to the comments/Seedling. If the window closes with zero events, no push is sent.",
