/**
 * Returns the matching NotificationRule for a given scenario id or key,
 * or fuzzy matches by engine + event name.
 */
export function getRuleForScenario(scenario: {
  id?: string
  key?: string
  ruleId?: string
  engineCategory?: string
  governanceEvent?: string
  audience?: string
}): NotificationRule | undefined {
  if (!scenario) return undefined

  // 1. Direct ruleId
  if (scenario.ruleId && RULES_BY_ID[scenario.ruleId]) {
    return RULES_BY_ID[scenario.ruleId]
  }

  // 2. Scenario ID map
  if (scenario.id && SCENARIO_ID_TO_RULE_ID[scenario.id]) {
    const mappedRuleId = SCENARIO_ID_TO_RULE_ID[scenario.id]
    if (RULES_BY_ID[mappedRuleId]) return RULES_BY_ID[mappedRuleId]
  }

  // 3. Fallback normalized match by engine + event name
  const norm = (s?: string) => (s || '').toLowerCase().replace(/[^a-z0-9]/g, '')
  const sEngine = norm(scenario.engineCategory)
  const sEvent = norm(scenario.governanceEvent)
  const sAud = norm(scenario.audience)

  const candidates = ALL_NOTIFICATION_RULES.filter(
    (r) => norm(r.engine) === sEngine && norm(r.ruleName) === sEvent
  )

  if (candidates.length === 1) return candidates[0]
  if (candidates.length > 1) {
    const audMatch = candidates.find(
      (r) => norm(r.audience) === sAud || norm(r.audience).includes(sAud) || sAud.includes(norm(r.audience))
    )
    if (audMatch) return audMatch
    return candidates[0]
  }

  // 4. Fuzzy search across all rules
  return ALL_NOTIFICATION_RULES.find((r) => norm(r.ruleName) === sEvent)
}
